package local.station.controller;
import android.app.Activity;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import android.animation.*;import android.os.*;import android.media.*;

/** A minimum-duration local startup, released only after a real connection or usable setup UI. */
final class StartScreen {
 private final Activity activity;private final LinearLayout cover;private final TextView state;private final long began=SystemClock.elapsedRealtime();private boolean done;private final Handler main=new Handler(Looper.getMainLooper());
 private int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}
 StartScreen(Activity a,FrameLayout host){activity=a;cover=new LinearLayout(a);cover.setOrientation(1);cover.setGravity(Gravity.CENTER);cover.setBackgroundColor(0xfff5f3f9);cover.setPadding(dp(24),0,dp(24),0);ImageView art=new ImageView(a);try{art.setImageDrawable(Drawable.createFromStream(a.getAssets().open("launch-star.png"),null));}catch(Exception ignored){}art.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.addView(art,new LinearLayout.LayoutParams(dp(210),dp(180)));TextView name=new TextView(a);name.setText("AliceKit");name.setTextSize(30);name.setTypeface(null,1);name.setTextColor(0xff29252f);name.setGravity(Gravity.CENTER);cover.addView(name);state=new TextView(a);state.setText("Проверяем подключение…");state.setTextColor(0xff81738f);state.setTextSize(15);state.setPadding(0,dp(18),0,0);state.setGravity(Gravity.CENTER);cover.addView(state);host.addView(cover,new FrameLayout.LayoutParams(-1,-1));art.setScaleX(.65f);art.setScaleY(.65f);art.setAlpha(0f);art.setRotation(-15);art.animate().alpha(1).scaleX(1).scaleY(1).rotation(0).setDuration(1500).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();name.setAlpha(0);name.animate().alpha(1).setStartDelay(700).setDuration(700).start();main.postDelayed(()->{if(done)return;state.setText("Подключение занимает больше времени. Можно перейти к настройке.");Button next=new Button(a);next.setText("Открыть подключение");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.topMargin=dp(26);cover.addView(next,p);next.setOnClickListener(v->ready("Продолжаем подключение"));},8000);sound();}
 long age(){return SystemClock.elapsedRealtime()-began;}
 void ready(String text){if(done)return;state.setText(text);main.postDelayed(()->{if(done)return;done=true;cover.animate().alpha(0).setDuration(350).withEndAction(()->{if(cover.getParent() instanceof ViewGroup)((ViewGroup)cover.getParent()).removeView(cover);}).start();},Math.max(0,2200-age()));}
 private void sound(){if(!activity.getSharedPreferences("appearance",0).getBoolean("startupSound",true))return;try{MediaPlayer player=new MediaPlayer();android.content.res.AssetFileDescriptor f=activity.getAssets().openFd("startup.wav");player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());player.setDataSource(f.getFileDescriptor(),f.getStartOffset(),f.getLength());f.close();player.setVolume(.14f,.14f);player.setOnCompletionListener(MediaPlayer::release);player.setOnErrorListener((p,w,e)->{p.release();return true;});player.prepare();player.start();}catch(Exception ignored){}}
 void close(){done=true;main.removeCallbacksAndMessages(null);}
}
